   737	    pub fn hash(self: Key, hasher: anytype) void {
   738	        const autoHash = std.hash.autoHash;
   739	        autoHash(hasher, @as(u32, @bitCast(self.font_size.points)));
   740	        autoHash(hasher, self.font_size.xdpi);
   741	        autoHash(hasher, self.font_size.ydpi);
   742	        autoHash(hasher, self.descriptors.len);
   743	        for (self.descriptors) |d| d.hash(hasher);
   744	        self.codepoint_map.hash(hasher);
   745	        autoHash(hasher, self.metric_modifiers.count());
   746	        autoHash(hasher, self.freetype_load_flags);
   747	        if (self.metric_modifiers.count() > 0) {
   748	            inline for (@typeInfo(Metrics.Key).@"enum".field_names) |field| {
   749	                const key = @field(Metrics.Key, field);
   750	                if (self.metric_modifiers.get(key)) |value| {
   751	                    autoHash(hasher, key);
   752	                    value.hash(hasher);
   753	                }
   754	            }
   755	        }
   756	    }
