   242	    /// Finds the controller whose split tree owns the given surface.
   243	    ///
   244	    /// A surface's `window` can briefly be nil or point at its previous window
   245	    /// while AppKit is attaching or moving a native tab. Callers performing
   246	    /// lifecycle operations must use tree ownership rather than that transient
   247	    /// view relationship.
   248	    static func controller(owning surface: Ghostty.SurfaceView) -> BaseTerminalController? {
   249	        if let controller = surfaceControllers.object(forKey: surface),
   250	           controller.surfaceTree.contains(surface) {
   251	            return controller
   252	        }
   253	
   254	        if let controller = surface.window?.windowController as? BaseTerminalController,
   255	           controller.surfaceTree.contains(surface) {
   256	            return controller
   257	        }
   258	
   259	        return NSApp.windows
   260	            .compactMap { $0.windowController as? BaseTerminalController }
   261	            .first { $0.surfaceTree.contains(surface) }
   262	    }
