   264	    private static func updateSurfaceControllers(
   265	        _ controller: BaseTerminalController,
   266	        from oldTree: SplitTree<Ghostty.SurfaceView>,
   267	        to newTree: SplitTree<Ghostty.SurfaceView>
   268	    ) {
   269	        for surface in oldTree where !newTree.contains(surface) {
   270	            if surfaceControllers.object(forKey: surface) === controller {
   271	                surfaceControllers.removeObject(forKey: surface)
   272	            }
   273	        }
   274	
   275	        for surface in newTree {
   276	            surfaceControllers.setObject(controller, forKey: surface)
   277	        }
   278	    }
