  1279	    // If we're no longer autoscrolling for whatever reason, disable it.
  1280	    if (self.mouse.selection_gesture.left_drag_autoscroll == .none) {
  1281	        self.queueIo(
  1282	            .{ .selection_scroll = false },
  1283	            .locked,
  1284	        );
